    for tag in ['scalars/eval_return', 'scalars/train_return', 'civo/ve_ratio', 'civo/alert', 'civo/delta_ve']:
        events = ea.Scalars(tag) if tag in ea.Tags().get('scalars', []) else []
        if events:
            print(f'  {tag}:')
